// Package subagents is the harness-neutral core of a nested agent run: where it
// is placed, where its transcript lives, its hooks, its isolation and what it
// hands back.
package subagents

import (
	"path/filepath"
	"strings"
)

// Layout is where a harness keeps sub-agent transcripts: in one directory
// beside the session's own transcript.
type Layout struct {
	// SessionExt is the session transcript's extension, which the directory
	// name drops: <session transcript without ext>/<Dir>/<Prefix><id><Ext>.
	SessionExt, Dir, Prefix, Ext string
	// SidecarExt replaces Ext on a sub-agent's transcript path to name the
	// metadata file that sits beside it.
	SidecarExt string
}

// Path is the transcript of sub-agent id for a session whose transcript is
// sessionFile: a file of its own in the session's sub-agent directory, never
// the session's. A nested sub-agent's is in the same directory as its parent's,
// since every sub-agent of a session is recorded there.
//
// sr:capability subagent-transcripts
func (l Layout) Path(sessionFile, id string) string {
	return filepath.Join(strings.TrimSuffix(sessionFile, l.SessionExt), l.Dir, l.Prefix+id+l.Ext)
}

// Sidecar is the metadata file beside the sub-agent transcript at path: the
// same name with the sidecar extension.
func (l Layout) Sidecar(path string) string {
	return strings.TrimSuffix(path, l.Ext) + l.SidecarExt
}

// Parent is the agent that dispatches a sub-agent: the main thread (ID "",
// depth 0) or a sub-agent.
type Parent struct {
	ID    string
	Depth int
}

// Placement is where a sub-agent sits in the tree of a session's agents.
type Placement struct {
	// Depth is how deep in sub-agents it is: 1 for a sub-agent of the main
	// thread, 2 for one that sub-agent dispatched.
	Depth int
	// ParentID is the dispatching sub-agent's id, "" for the main thread.
	ParentID string
}

// Place is the placement of a sub-agent dispatched by parent: one deeper, naming
// the parent. A sub-agent can itself dispatch sub-agents.
//
// sr:capability nested-subagents
func Place(parent Parent) Placement {
	return Placement{Depth: parent.Depth + 1, ParentID: parent.ID}
}

// DefaultSpawnLimit is how many layers of sub-agents a session can nest below
// its main thread when the harness is not told otherwise.
const DefaultSpawnLimit = 3

// CanDispatch reports whether parent may dispatch a sub-agent when a session
// nests at most limit layers deep (a limit of 0 is the default, a negative or
// 1 turns nesting off for sub-agents): the main thread always may, and a
// sub-agent only while it is above the limit.
func (p Parent) CanDispatch(limit int) bool {
	if limit == 0 {
		limit = DefaultSpawnLimit
	}
	return p.Depth < limit
}
package subagents

import (
	"github.com/sloprail/harness-mocks/internal/tasks"
	"github.com/sloprail/harness-mocks/internal/turnloop"
)

// Outcome is how one run of a sub-agent ended.
type Outcome struct {
	// FinalText is its final report, LastAssistant the text of its last message.
	FinalText, LastAssistant string
	// Failure is why it failed, "" when it did not.
	Failure  string
	ToolUses int
}

// Hooks are what a harness fires around a sub-agent.
type Hooks struct {
	// Start fires when the sub-agent starts. It cannot block the sub-agent, so it
	// returns nothing: the sub-agent runs whatever the hook did.
	Start func()
	// Stop fires when the sub-agent stops, with whether an earlier stop hook
	// blocked it already (active) and its last message; it reports whether it
	// blocked, and why.
	Stop func(active bool, last string) (blocked bool, reason string)
	// OnRerun and OnCap, when set, report a re-run after a block and a block cap
	// being reached.
	OnRerun func(reason string, turn int)
	OnCap   func(blockCap int)
}

// StopFacts is what a sub-agent's stop hook is told: the sub-agent's own
// transcript, its last message, and the session's background tasks (not only
// the sub-agent's).
type StopFacts struct {
	TranscriptPath, LastMessage string
	Tasks                       []*tasks.Task
}

// Stop is the facts of a sub-agent's stop for the hook: its own transcript
// path and last message, and every background task still running in the session.
//
// sr:capability subagent-lifecycle-hooks
func Stop(transcriptPath, last string, session *tasks.Registry) StopFacts {
	return StopFacts{TranscriptPath: transcriptPath, LastMessage: last, Tasks: session.Running()}
}

// Execute fires the start hook, runs the sub-agent, and re-runs it while the stop
// hook blocks: the hook's reason is its feedback, until the hook lets the
// sub-agent stop or blockCap consecutive blocks have been honoured (0: no cap).
// It returns how the last run ended, its tool uses summed over every run.
//
// sr:capability subagent-stop-block-loop
func Execute(h Hooks, blockCap int, run func() Outcome) Outcome {
	if h.Start != nil {
		h.Start()
	}
	out := run()
	for turn := 0; ; turn++ {
		blocked, reason := h.Stop(turn > 0, out.LastAssistant)
		if !blocked {
			return out
		}
		if !turnloop.AfterBlock(turn+1, blockCap) {
			if h.OnCap != nil {
				h.OnCap(blockCap)
			}
			return out
		}
		if h.OnRerun != nil {
			h.OnRerun(reason, turn+1)
		}
		next := run()
		next.ToolUses += out.ToolUses
		out = next
	}
}

// Begin fires the start hook now and returns what finishes the sub-agent
// later: running it and the stop-hook loop, as Execute does after its start
// hook. A sub-agent that runs in the background is begun when it is launched,
// before the launching call is answered, and finished once its run starts.
func Begin(h Hooks) func(blockCap int, run func() Outcome) Outcome {
	if h.Start != nil {
		h.Start()
	}
	h.Start = nil
	return func(blockCap int, run func() Outcome) Outcome { return Execute(h, blockCap, run) }
}
