package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/spf13/cobra"

	"github.com/sloprail/harness-mocks/codex-mock/internal/runner"
)

// newExec is `exec`, the non-interactive run. It accepts the flags a real
// `codex exec` accepts and has no use for, so a caller's command line works
// unchanged.
func newExec() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "exec [flags] [prompt]",
		Short: "Run the scenario script as a non-interactive Codex session",
		RunE:  runExec,
	}
	f := cmd.Flags()
	f.String("script", "", "Scenario script that drives the agent (env: A10N_MOCK_SCRIPT)")
	f.Bool("json", false, "Print events to stdout as JSONL")
	f.StringP("cd", "C", "", "Working directory of the session (default: the current one)")
	f.StringP("model", "m", "", "Model name reported in hook payloads")
	// Accepted for compatibility with `codex exec`; no effect.
	f.StringArrayP("config", "c", nil, "Accepted; no effect")
	f.StringArray("enable", nil, "Accepted; no effect")
	f.StringArray("disable", nil, "Accepted; no effect")
	f.StringP("sandbox", "s", "", "Accepted; no effect")
	f.StringP("profile", "p", "", "Accepted; no effect")
	f.String("color", "", "Accepted; no effect")
	f.StringP("output-last-message", "o", "", "Accepted; no effect")
	f.String("output-schema", "", "Accepted; no effect")
	f.String("thread-source", "", "Accepted; no effect")
	for _, name := range []string{"skip-git-repo-check", "ephemeral", "ignore-user-config", "ignore-rules",
		"strict-config", "dangerously-bypass-approvals-and-sandbox", "dangerously-bypass-hook-trust", "approve-for-me"} {
		f.Bool(name, false, "Accepted; no effect")
	}
	return cmd
}

func runExec(cmd *cobra.Command, args []string) error {
	f := cmd.Flags()
	script, _ := f.GetString("script")
	if script == "" {
		script = os.Getenv("A10N_MOCK_SCRIPT")
	}
	cwd, _ := f.GetString("cd")
	if cwd == "" {
		var err error
		if cwd, err = os.Getwd(); err != nil {
			return fmt.Errorf("codex-mock: getwd: %w", err)
		}
	}
	if resolved, err := filepath.EvalSymlinks(cwd); err == nil {
		cwd = resolved
	}
	home := os.Getenv("CODEX_HOME")
	if home == "" {
		user, err := os.UserHomeDir()
		if err != nil {
			return fmt.Errorf("codex-mock: no CODEX_HOME and no home directory: %w", err)
		}
		home = filepath.Join(user, ".codex")
	}
	asJSON, _ := f.GetBool("json")
	model, _ := f.GetString("model")
	return runner.Run(cmd.Context(), runner.Config{
		Script: script, Prompt: strings.Join(args, " "), Cwd: cwd, CodexHome: home, Model: model,
		Environ: os.Environ(), JSON: asJSON, Stdout: cmd.OutOrStdout(), Stderr: os.Stderr,
	})
}
// Package runner is one `codex exec` run: the session, its hooks, and the turn.
package runner

import (
	"context"
	"errors"
	"fmt"
	"io"
	"time"

	"github.com/sloprail/harness-mocks/codex-mock/internal/childenv"
	"github.com/sloprail/harness-mocks/codex-mock/internal/events"
	"github.com/sloprail/harness-mocks/codex-mock/internal/hooks"
	"github.com/sloprail/harness-mocks/codex-mock/internal/session"
	coresession "github.com/sloprail/harness-mocks/internal/session"
	"github.com/sloprail/harness-mocks/internal/turnloop"
)

// Config is everything a run is told, read once at the entrypoint.
type Config struct {
	// Script is the scenario script that drives the agent.
	Script string
	Prompt string
	// Cwd is the session's working directory.
	Cwd string
	// CodexHome holds the user's hooks.json and the session's rollout.
	CodexHome string
	Model     string
	// Environ is the environment the mock was started with.
	Environ []string
	// JSON prints the event stream on Stdout; otherwise Stdout gets the
	// agent's final message.
	JSON           bool
	Stdout, Stderr io.Writer
}

// state is the state of one run, shared by Codex's side of the turn and of
// its tool calls.
type state struct {
	cfg     Config
	id      string
	turnID  string
	hooks   *hooks.Invoker
	events  *events.Stream
	rollout *session.File
	toolEnv []string
}

// Run starts the session, fires SessionStart, and runs one turn.
// sr:provides session-start-hook/codex
// sr:provides session-end-hook/codex
// sr:provides noninteractive-run/codex
func Run(ctx context.Context, cfg Config) error {
	if cfg.Script == "" {
		return errors.New("codex-mock: a scenario script is required (--script or A10N_MOCK_SCRIPT)")
	}
	hookCfg, err := hooks.Load(cfg.CodexHome, cfg.Cwd)
	if err != nil {
		return fmt.Errorf("codex-mock: cannot load hooks: %w", err)
	}
	id := coresession.NewID()
	rollout, err := session.Create(cfg.CodexHome, id, cfg.Cwd, time.Now())
	if err != nil {
		return fmt.Errorf("codex-mock: cannot create the session file: %w", err)
	}
	defer rollout.Close()
	out := cfg.Stdout
	if !cfg.JSON {
		out = io.Discard
	}
	s := &state{cfg: cfg, id: id, turnID: coresession.NewID(), rollout: rollout, events: events.New(out),
		toolEnv: childenv.ToolEnv(cfg.Environ, id)}
	s.hooks = &hooks.Invoker{Config: hookCfg, Dir: cfg.Cwd, Environ: cfg.Environ, Ident: childenv.HookIdentity(),
		Common: hooks.Common{SessionID: id, TranscriptPath: rollout.Path, Cwd: cfg.Cwd, Model: cfg.Model,
			PermissionMode: "bypassPermissions"}}
	s.events.ThreadStarted(id)
	for _, o := range s.hooks.Fire(ctx, hooks.SessionStart, "startup", map[string]any{"source": "startup"}) {
		if d := hooks.Interpret(hooks.SessionStart, o); d.Context != "" {
			rollout.Developer(d.Context)
		}
	}
	s.events.TurnStarted()
	last, err := turnloop.Run(ctx, turnHost{s}, turnloop.Params{
		Script: cfg.Script, Dir: cfg.Cwd, Environ: cfg.Environ, Prompt: cfg.Prompt})
	s.events.TurnCompleted()
	// The session ends with the run, for the one reason a non-interactive run has;
	// what the hook prints is not read.
	s.hooks.Fire(ctx, hooks.SessionEnd, "other", map[string]any{"reason": "other"})
	if !cfg.JSON && last != "" {
		fmt.Fprintln(cfg.Stdout, last)
	}
	return err
}

