package runner

import (
	"context"
	"encoding/json"
	"io"
	"os"
	"sync"
	"time"

	"github.com/sloprail/harness-mocks/codex-mock/internal/childenv"
	"github.com/sloprail/harness-mocks/codex-mock/internal/events"
	"github.com/sloprail/harness-mocks/codex-mock/internal/hooks"
	"github.com/sloprail/harness-mocks/codex-mock/internal/session"
	coresession "github.com/sloprail/harness-mocks/internal/session"
	"github.com/sloprail/harness-mocks/internal/scenario"
	"github.com/sloprail/harness-mocks/internal/subagents"
	"github.com/sloprail/harness-mocks/internal/turnloop"
)

// Codex's multi-agent tools: spawn_agent starts a sub-agent (a thread of its
// own) and the wait tool collects its final message. Hooks name the wait tool
// multi_agent_v1wait_agent (recorded: runs/nested-subagents).
const (
	spawnTool    = "spawn_agent"
	waitTool     = "wait_agent"
	waitHookName = "multi_agent_v1wait_agent"
	waitEvent    = "wait"
	// DefaultAgentDepth is how many layers of sub-agents Codex lets a session
	// nest when agents.max_depth is not set: one, so a sub-agent cannot spawn
	// (recorded: runs/nested-subagents-limit, run with max_depth 2).
	DefaultAgentDepth = 1
	// envSubagentScript names the scenario script a sub-agent runs when the
	// spawn_agent call does not carry a `script` of its own.
	envSubagentScript = "A10N_MOCK_SUBAGENT_SCRIPT"
	agentType         = "default"
)

// agentPos is where the agent making a tool call sits: the main thread (ID "",
// depth 0) or a sub-agent. It travels in the context of the agent's turn.
type agentPos struct {
	ID    string
	Depth int
}

type agentKey struct{}

func agentOf(ctx context.Context) agentPos {
	p, _ := ctx.Value(agentKey{}).(agentPos)
	return p
}

// finished is the final message of every sub-agent that has ended, by thread
// id: what the wait tool hands back. One run per process, so one table.
var finished sync.Map

// agentTool carries out spawn_agent and the wait tool, and reports whether it
// did. A sub-agent at the depth limit is not offered either (recorded: its tool
// search finds nothing), so they are not tools there and fall through to the
// call every unknown tool gets.
func (h turnHost) agentTool(ctx context.Context, tu scenario.ToolUse) bool {
	if tu.Name != spawnTool && tu.Name != waitTool {
		return false
	}
	pos := agentOf(ctx)
	if !(subagents.Parent{ID: pos.ID, Depth: pos.Depth}).CanDispatch(h.depthLimit()) {
		return false
	}
	h.rollout.ToolCall(tu.ID, tu.Name, tu.Input)
	if tu.Name == spawnTool {
		h.spawn(ctx, tu, pos)
	} else {
		h.wait(ctx, tu, pos)
	}
	return true
}

// depthLimit is how many layers of sub-agents this run lets a session nest.
func (h turnHost) depthLimit() int {
	if h.cfg.AgentMaxDepth > 0 {
		return h.cfg.AgentMaxDepth
	}
	return DefaultAgentDepth
}

// fireAgentHook fires PreToolUse for a multi-agent call by agent pos: a
// sub-agent's calls name it (agent_id, agent_type) in their payload.
func (h turnHost) fireAgentHook(ctx context.Context, tu scenario.ToolUse, name string, input any, pos agentPos) {
	own := map[string]any{"turn_id": h.turnID, "tool_name": name, "tool_use_id": tu.ID, "tool_input": input}
	if pos.ID != "" {
		own["agent_id"], own["agent_type"] = pos.ID, agentType
	}
	h.hooks.Fire(ctx, hooks.PreToolUse, name, own)
}

// thread is the id Codex gives the agent at pos: the session's for the main
// thread, its own for a sub-agent.
func (h turnHost) thread(pos agentPos) string {
	if pos.ID == "" {
		return h.id
	}
	return pos.ID
}

// spawn starts a sub-agent, one layer deeper than the agent that spawned it
// (the core's placement), with a rollout of its own beside the session's that
// names its parent thread and depth; it runs the sub-agent's script to its end
// before the call returns (the mock has no concurrency). Only the main
// thread's tool calls are in the event stream.
// sr:provides nested-subagents/codex
func (h turnHost) spawn(ctx context.Context, tu scenario.ToolUse, pos agentPos) {
	var in struct{ Message, Script string }
	_ = json.Unmarshal(tu.Input, &in)
	h.fireAgentHook(ctx, tu, spawnTool, map[string]string{"message": in.Message}, pos)
	sender := h.thread(pos)
	evID := h.events.CollabStarted(spawnTool, sender, nil, &in.Message)

	place := subagents.Place(subagents.Parent{ID: sender, Depth: pos.Depth})
	childID := coresession.NewID()
	rollout, err := session.CreateSub(h.cfg.CodexHome, childID, h.cfg.Cwd, time.Now(),
		session.Origin{Session: h.hooks.Common.SessionID, Parent: place.ParentID, Depth: place.Depth})
	if err != nil {
		h.rollout.ToolOutput(tu.ID, "failed to spawn agent: "+err.Error())
		return
	}
	defer rollout.Close()
	script := in.Script
	if script == "" {
		script = os.Getenv(envSubagentScript)
	}
	cfg := h.cfg
	cfg.Prompt, cfg.Script = in.Message, script
	hk := *h.hooks
	hk.Common.TranscriptPath = rollout.Path
	child := &state{cfg: cfg, id: childID, turnID: coresession.NewID(), hooks: &hk, events: events.New(io.Discard),
		rollout: rollout, toolEnv: childenv.ToolEnv(cfg.Environ, childID)}
	last, _ := turnloop.Run(context.WithValue(ctx, agentKey{}, agentPos{ID: childID, Depth: place.Depth}),
		subTurnHost{turnHost{child}}, turnloop.Params{Script: script, Dir: cfg.Cwd, Environ: cfg.Environ, Prompt: in.Message})
	finished.Store(childID, last)

	h.events.CollabCompleted(evID, spawnTool, sender, []string{childID}, &in.Message,
		map[string]events.AgentState{childID: {Status: "pending_init"}})
	out, _ := json.Marshal(map[string]string{"agent_id": childID})
	h.rollout.ToolOutput(tu.ID, string(out))
}

// wait hands back the final message of each sub-agent it is told to wait for.
func (h turnHost) wait(ctx context.Context, tu scenario.ToolUse, pos agentPos) {
	var in struct {
		Targets []string `json:"targets"`
	}
	_ = json.Unmarshal(tu.Input, &in)
	h.fireAgentHook(ctx, tu, waitHookName, json.RawMessage(tu.Input), pos)
	sender := h.thread(pos)
	evID := h.events.CollabStarted(waitEvent, sender, in.Targets, nil)
	states, status := map[string]events.AgentState{}, map[string]map[string]string{}
	for _, id := range in.Targets {
		msg, _ := finished.Load(id)
		text, _ := msg.(string)
		states[id] = events.AgentState{Status: "completed", Message: &text}
		status[id] = map[string]string{"completed": text}
	}
	h.events.CollabCompleted(evID, waitEvent, sender, in.Targets, nil, states)
	out, _ := json.Marshal(map[string]any{"status": status, "timed_out": false})
	h.rollout.ToolOutput(tu.ID, string(out))
}

// subTurnHost is a sub-agent's turn: it starts from its message with no
// prompt hook, and ends with no Stop hook (recorded: only the main thread's
// Stop reached the hook log).
type subTurnHost struct{ turnHost }

func (h subTurnHost) SubmitPrompt(context.Context) (string, bool) {
	h.rollout.User(h.cfg.Prompt)
	return "", false
}

func (h subTurnHost) EndOfTurn(context.Context, string, bool) (string, bool) { return "", false }

