package runner

import (
	"sync"

	"github.com/sloprail/harness-mocks/internal/subagents"
)

// Codex's multi-agent tools: spawn_agent starts a sub-agent (a thread of its
// own) and the wait tool collects its final message. Hooks name the wait tool
// multi_agent_v1wait_agent (recorded: runs/nested-subagents).
const (
	spawnTool    = "spawn_agent"
	waitTool     = "wait_agent"
	waitHookName = "multi_agent_v1wait_agent"
	waitEvent    = "wait"
	agentType    = "default"
	// DefaultAgentDepth is how many layers of sub-agents Codex lets a session
	// nest when agents.max_depth is not set: one, so a sub-agent cannot spawn
	// (recorded: runs/nested-subagents-limit, run with max_depth 2).
	DefaultAgentDepth = 1
)

// AgentSettings is what the entrypoint read of the command line and the
// environment for sub-agents.
type AgentSettings struct {
	// MaxDepth is agents.max_depth, zero when not set.
	MaxDepth int
	// Script is the scenario script a sub-agent runs when its spawn_agent call
	// does not carry one (A10N_MOCK_SUBAGENT_SCRIPT).
	Script string
}

// Agents is set once by the entrypoint, before Run.
var Agents AgentSettings

// agentPos is where a thread sits: the main thread (ID "", depth 0) or a
// sub-agent.
type agentPos struct {
	ID    string
	Depth int
}

// threads is the position of every sub-agent started, by thread id (the main
// thread is in none), and finished the final message of each that ended: what
// the wait tool hands back. One run per process, so one table of each.
var threads, finished sync.Map

func posOf(thread string) agentPos {
	p, _ := threads.Load(thread)
	pos, _ := p.(agentPos)
	return pos
}

// canDispatch is whether the agent at pos is offered the multi-agent tools: a
// sub-agent at the depth limit is not (recorded: its tool search finds
// nothing), so a call of them there is the unknown tool every other is.
func canDispatch(pos agentPos) bool {
	limit := Agents.MaxDepth
	if limit <= 0 {
		limit = DefaultAgentDepth
	}
	return subagents.Parent{ID: pos.ID, Depth: pos.Depth}.CanDispatch(limit)
}

func isAgentTool(name string) bool { return name == spawnTool || name == waitTool }

