package runner

import (
	"context"
	"encoding/json"

	"github.com/sloprail/harness-mocks/codex-mock/internal/hooks"
	"github.com/sloprail/harness-mocks/internal/toolcall"
)

// The multi-agent tools' side of toolHost: the tool's parameters, and the
// before-tool hooks, whose payload names a sub-agent making the call
// (agent_id, agent_type) and does not name the main thread.

// agentParams are the parameters a call to a multi-agent tool must carry, and
// whether the agent making it is offered the tool.
func (h toolHost) agentParams(name string) ([]string, bool) {
	if !isAgentTool(name) || !canDispatch(posOf(h.id)) {
		return nil, false
	}
	if name == spawnTool {
		return []string{"message"}, true
	}
	return []string{"targets"}, true
}

// agentBefore fires PreToolUse for a multi-agent call and asks for the
// refusal of what the hooks decided.
func (h toolHost) agentBefore(ctx context.Context, c toolcall.Call) (bool, string) {
	name, input := c.Name, any(json.RawMessage(c.Input))
	if name == spawnTool {
		var in struct{ Message string }
		_ = json.Unmarshal(c.Input, &in)
		input = map[string]string{"message": in.Message}
	} else {
		name = waitHookName
	}
	own := map[string]any{"turn_id": h.turnID, "tool_name": name, "tool_use_id": c.ID, "tool_input": input}
	if pos := posOf(h.id); pos.ID != "" {
		own["agent_id"], own["agent_type"] = pos.ID, agentType
	}
	var ds []hooks.Decision
	for _, o := range h.hooks.Fire(ctx, hooks.PreToolUse, name, own) {
		ds = append(ds, hooks.Interpret(hooks.PreToolUse, o))
	}
	return hooks.Refusal(ds)
}

