package runner

import (
	"context"
	"fmt"
	"strings"

	"github.com/sloprail/harness-mocks/cursor-mock/internal/hooks"
	"github.com/sloprail/harness-mocks/cursor-mock/internal/toolexec"
	corehooks "github.com/sloprail/harness-mocks/internal/hooks"
	"github.com/sloprail/harness-mocks/internal/toolcall"
)

// taskHost is the harness side (toolcall.Host) of a Task call, which starts a
// sub-agent: preToolUse fires for it in the session of the agent making it
// (and that is the only hook recorded: runs/nested-subagents), and what the
// sub-agent said last is what the agent is told.
type taskHost struct {
	s     *session
	depth int
	// call is the call as the stream shows it.
	call toolexec.Call
}

// Tool: a Task call needs a description of the task and a prompt.
func (h *taskHost) Tool(name string) ([]string, bool) {
	return []string{"description", "prompt"}, name == taskTool
}

// Before fires preToolUse and asks for the refusal of what the hooks decided.
func (h *taskHost) Before(ctx context.Context, c toolcall.Call) (bool, string) {
	var in map[string]any
	_ = jsonUnmarshal(c.Input, &in)
	delete(in, "script") // the mock's own field
	refused, msg := hooks.Refusal(h.s.hooks.Fire(ctx, hooks.PreToolUse, taskTool,
		map[string]any{"tool_name": taskTool, "tool_input": in, "tool_use_id": c.ID}))
	h.s.named = true
	return refused, msg
}

// Execute starts the sub-agent and prints the call's completed frame with what
// it said.
func (h *taskHost) Execute(ctx context.Context, c toolcall.Call) toolcall.Result {
	final := h.s.runSubagent(ctx, c, h.call, h.depth)
	return toolcall.Result{Output: final}
}

// After fires nothing: no hook was recorded after a Task call.
func (h *taskHost) After(context.Context, toolcall.Call, toolcall.Result, corehooks.AfterTool) (string, bool) {
	return "", false
}

// Answer tells the agent how a call that did not run ended; one that ran has
// been told by its completed frame.
func (h *taskHost) Answer(c toolcall.Call, a toolcall.Answer) {
	switch a.Kind {
	case toolcall.Refused:
		h.s.forward(errorFrame(h.s.id, c.ID, h.call, a.Reason))
	case toolcall.Invalid:
		h.s.forward(errorFrame(h.s.id, c.ID, h.call, fmt.Sprintf("%s: missing required parameter(s): %s", c.Name, strings.Join(a.Missing, ", "))))
	}
}

