package runner

import (
	"context"
	"encoding/json"
	"io"
	"strings"
	"time"

	"github.com/sloprail/harness-mocks/cursor-mock/internal/hooks"
	"github.com/sloprail/harness-mocks/cursor-mock/internal/toolexec"
	"github.com/sloprail/harness-mocks/internal/scenario"
	coresession "github.com/sloprail/harness-mocks/internal/session"
	"github.com/sloprail/harness-mocks/internal/subagents"
	"github.com/sloprail/harness-mocks/internal/toolcall"
	"github.com/sloprail/harness-mocks/internal/turnloop"
)

const (
	// taskTool is Cursor's tool for starting a sub-agent.
	taskTool = "Task"
	// agentDepthLimit is how many layers of sub-agents Cursor lets a session
	// nest: two. The main thread's sub-agent can start one of its own, and
	// that one is not offered the tool (recorded: runs/nested-subagents-depth,
	// where it said no Task tool is available).
	agentDepthLimit = 2
)

func jsonUnmarshal(b []byte, v any) error { return json.Unmarshal(b, v) }

// depthKey carries how deep in sub-agents the agent making a tool call is
// (0 for the main thread) in the context of its turn.
type depthKey struct{}

func depthOf(ctx context.Context) int {
	d, _ := ctx.Value(depthKey{}).(int)
	return d
}

// task handles a Task call and reports whether it did. A sub-agent at the depth
// limit is not offered the tool, so a call of it is the unknown tool every
// other is.
func (s *session) task(ctx context.Context, tu scenario.ToolUse) bool {
	depth := depthOf(ctx)
	if tu.Name != taskTool || !(subagents.Parent{ID: s.id, Depth: depth}).CanDispatch(agentDepthLimit) {
		return false
	}
	var in struct {
		Description, Prompt string
	}
	_ = json.Unmarshal(tu.Input, &in)
	call := toolexec.Call{Kind: "taskToolCall", Args: map[string]any{"description": in.Description,
		"prompt": in.Prompt, "subagentType": map[string]any{"unspecified": map[string]any{}}, "model": "default"}}
	s.forward(startedFrame(s.id, tu.ID, call))
	s.tr.toolUse(taskTool, map[string]any{"description": in.Description, "prompt": in.Prompt})
	toolcall.Run(ctx, &taskHost{s: s, depth: depth, call: call},
		toolcall.Call{ID: tu.ID, Name: tu.Name, Input: tu.Input}, toolcall.Options{})
	return true
}

// runSubagent starts a sub-agent for a Task call, one layer deeper than the
// agent making it (the core's placement). It is a conversation of its own: its
// own id (which its hooks report as their session), its own transcript in the
// one agent-transcripts directory of the workspace, and its own hooks, which see
// the same configuration. It runs the scenario script to its end before the
// call returns, and what it said last is handed to the agent: the call's
// completed frame, and a message of the agent's own (recorded:
// runs/nested-subagents). It returns that text.
// sr:provides nested-subagents/cursor
func (s *session) runSubagent(ctx context.Context, c toolcall.Call, call toolexec.Call, depth int) string {
	var in struct {
		Prompt string `json:"prompt"`
		Script string `json:"script"`
	}
	_ = json.Unmarshal(c.Input, &in)
	script := in.Script
	if script == "" {
		script = s.cfg.SubagentScript
	}
	place := subagents.Place(subagents.Parent{ID: s.id, Depth: depth})
	cfg := s.cfg
	cfg.Script, cfg.Prompt, cfg.Stdout = script, in.Prompt, io.Discard
	child := &session{cfg: cfg, id: coresession.NewID(), started: time.Now()}
	var err error
	if child.tr, err = newTranscript(cfg.Home, cfg.Dir, child.id); err != nil {
		s.forward(errorFrame(s.id, c.ID, call, err.Error()))
		return ""
	}
	child.hooks = &hooks.Hooks{Config: s.hooks.Config, Dir: cfg.Dir, Env: child.hookEnv, Common: child.common}
	child.tr.user(in.Prompt)
	_, _ = turnloop.Run(context.WithValue(ctx, depthKey{}, place.Depth), child, turnloop.Params{
		Script: script, Dir: cfg.Dir, Environ: cfg.Environ, Prompt: in.Prompt, Added: child.Context})
	child.named = true
	child.tr.end()

	final := strings.Join(child.texts, "")
	s.forward(completedFrame(s.id, c.ID, call, map[string]any{"success": map[string]any{
		"conversationSteps": []any{map[string]any{"assistantMessage": map[string]any{"text": final}}},
		"agentId":           child.id, "isBackground": false, "durationMs": time.Since(child.started).Milliseconds()}}))
	s.Say(final)
	return final
}

