// hooks give it, and its input.
func (h toolHost) agentPayload(c toolcall.Call) (string, map[string]any) {
	name, input := c.Name, any(json.RawMessage(c.Input))
	if name == spawnTool {
		var in struct{ Message string }
		_ = json.Unmarshal(c.Input, &in)
		input = map[string]string{"message": in.Message}
	} else {
		name = waitHookName
	}
