	name, own := h.agentPayload(c)
	var ds []hooks.Decision
	for _, o := range h.hooks.Fire(ctx, hooks.PreToolUse, name, own) {
		ds = append(ds, hooks.Interpret(hooks.PreToolUse, o))
	}
	return hooks.Refusal(ds)
}

// agentAfter fires PostToolUse for a multi-agent call that ran, with what the
// agent was told as the response; a hook that blocks gives the agent its
// feedback in its place.
func (h toolHost) agentAfter(ctx context.Context, c toolcall.Call, r toolcall.Result) (string, bool) {
	name, own := h.agentPayload(c)
	own["tool_response"] = r.Output
	for _, o := range h.hooks.Fire(ctx, hooks.PostToolUse, name, own) {
		d := hooks.Interpret(hooks.PostToolUse, o)
		switch {
		case d.Blocked:
			return d.BlockReason, true
		case d.Denied:
			return d.DenyReason, true
		}
	}
	return "", false
}
