package runner

import (
	"context"
	"encoding/json"

	"github.com/sloprail/harness-mocks/codex-mock/internal/hooks"
	"github.com/sloprail/harness-mocks/internal/toolcall"
)

// The multi-agent tools' side of toolHost: the tool's parameters, and the hooks
// around a call, whose payload names a sub-agent making the call (agent_id,
// agent_type, for every tool it uses) and does not name the main thread
// (recorded: runs/nested-subagents).

// byAgent adds to a tool hook's own fields the agent making the call, when it
// is a sub-agent.
func (h toolHost) byAgent(own map[string]any) map[string]any {
	if pos := posOf(h.id); pos.ID != "" {
		own["agent_id"], own["agent_type"] = pos.ID, agentType
	}
	return own
}

// agentParams are the parameters a call to a multi-agent tool must carry, and
// whether the agent making it is offered the tool.
func (h toolHost) agentParams(name string) ([]string, bool) {
	if !isAgentTool(name) || !canDispatch(posOf(h.id)) {
		return nil, false
	}
	if name == agentTool {
		return agentRequired, true
	}
	return []string{"targets"}, true
}

// agentInput is a multi-agent call's input as hooks see it: without the
// mock's own `script` field.
func agentInput(c toolcall.Call) any {
	var in map[string]any
	if json.Unmarshal(c.Input, &in) != nil {
		return json.RawMessage(c.Input)
	}
	delete(in, "script")
	return in
}

// agentAfter fires PostToolUse for a multi-agent call that ran, with what the
// agent was told as the response; a hook that blocks gives the agent its
// feedback in its place.
