// chainScript is a sub-agent's scenario script: it spawns the sub-agent whose
// script is next, waits for it and says LEAF; with no next it runs the shell
// command echo LEAF and says LEAF.
// A spawn_agent the harness answers as an unknown tool leaves nothing to wait for.
func chainScript(next string) string {
	spawn := `{"message":"go","script":"` + next + `"}`
	say := `printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"text","text":"LEAF"}]}}' '{"type":"result","subtype":"success","result":"LEAF"}'`
	if next == "" {
		return `#!/bin/sh
n=$(grep -c function_call_output "$A10N_MOCK_SESSION_FILE")
if [ "$n" = 0 ]; then
  printf '%s\n' '{"type":"assistant","message":{"content":[{"type":"tool_use","id":"call_0","name":"Bash","input":{"command":"echo LEAF"}}]}}'
  exit 0
fi
` + say + "\n"
	}
	return fmt.Sprintf(`#!/bin/sh
n=$(grep -c function_call_output "$A10N_MOCK_SESSION_FILE")
call() { printf '{"type":"assistant","message":{"content":[{"type":"tool_use","id":"call_%%s","name":"%%s","input":%%s}]}}\n' "$n" "$1" "$2"; }
case $n in
0) call spawn_agent '%s' ;;
1) id=$(grep function_call_output "$A10N_MOCK_SESSION_FILE" | tail -1 | jq -r '(try (.payload.output | fromjson | .agent_id) catch "")')
   if [ -n "$id" ]; then call wait_agent "{\"targets\":[\"$id\"],\"timeout_ms\":3600000}"; exit 0; fi ;;
esac
%s
`, spawn, say)
}

// chain runs the mock on the recorded run's setup with a main-thread script
// that spawns a chain of sub-agents `layers` deep, under the given extra args.
func chain(t *testing.T, name string, layers int, args ...string) result {
	t.Helper()
	leaf := filepath.Join(t.TempDir(), "leaf.sh")
	require.NoError(t, os.WriteFile(leaf, []byte(chainScript("")), 0o755))
	main := `#!/bin/sh
