		path := map[string]any{"file_path": c.Args["path"]}
		s.runTool(ctx, scenario.ToolUse{ID: tu.ID + "-read", Name: "Read", Input: jsonLine(path)}, true)
	}
	s.runTool(ctx, tu, false)
}

